from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}  # id -> dict
        self._next_id = 1
        self._blocked = []  # list of (doctor, start, end)

    def _overlaps(self, start1, end1, start2, end2):
        return start1 < end2 and start2 < end1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment in the past")
        if end <= start:
            raise ValueError("End must be after start")

        # Check doctor availability
        for appt in self._appointments.values():
            if appt["doctor"] == doctor and not appt["cancelled"]:
                if self._overlaps(appt["start"], appt["end"], start, end):
                    raise ValueError("Doctor is not available in this time slot")

        for (bdoctor, bstart, bend) in self._blocked:
            if bdoctor == doctor and self._overlaps(bstart, bend, start, end):
                raise ValueError("Doctor is not available in this time slot")

        # Check patient's upcoming appointments
        for appt in self._appointments.values():
            if appt["patient"] == patient and not appt["cancelled"]:
                if appt["end"] > now:
                    raise ValueError(
                        "Patient already has an upcoming appointment"
                    )

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise ValueError("Appointment not found")
        appt = self._appointments[appointment_id]
        if appt["cancelled"]:
            raise ValueError("Appointment already cancelled")

        if appt["start"] - now < timedelta(hours=24):
            # Less than 24h before start: keep slot blocked
            self._blocked.append(
                (appt["doctor"], appt["start"], appt["end"])
            )
        appt["cancelled"] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        if end <= start:
            return False
        for appt in self._appointments.values():
            if appt["doctor"] == doctor and not appt["cancelled"]:
                if self._overlaps(appt["start"], appt["end"], start, end):
                    return False
        for (bdoctor, bstart, bend) in self._blocked:
            if bdoctor == doctor and self._overlaps(bstart, bend, start, end):
                return False
        return True
